// Applies the SQL migrations generated by drizzle-kit (migrations/, embedded at generate time).
import { sql } from 'drizzle-orm';
import { readMigrationFiles, type MigrationMeta } from 'drizzle-orm/migrator';
import { closeDb, createDb, type Db } from './client';
import { MIGRATIONS } from './migrations.generated';

export interface MigrateOptions {
  /** Read migrations from this folder instead of the embedded copy. */
  migrationsFolder?: string;
}

export function embeddedMigrations(): MigrationMeta[] {
  return MIGRATIONS.map((m) => ({
    sql: [...m.sql],
    bps: m.bps,
    folderMillis: m.folderMillis,
    hash: m.hash,
  }));
}

/** Advisory lock key that serialises concurrent `migrate` calls (api, worker, realtime at boot). */
export const MIGRATE_LOCK_KEY = 0x736b69726d; // "skirm"

/** True when a migration adds an enum value (`ALTER TYPE ... ADD VALUE`). */
export function addsEnumValue(m: Pick<MigrationMeta, 'sql'>): boolean {
  return m.sql.some((stmt) => /\bADD\s+VALUE\b/i.test(stmt));
}

/**
 * The next run of pending migrations to apply in one transaction: everything after `lastMillis`,
 * up to and including the first migration that adds an enum value. Postgres refuses to use an
 * enum value in the transaction that added it ("unsafe use of new value"), so that migration's
 * transaction must commit before a later migration may use the value (e.g. 0003 adds
 * registry_status 'local', 0011 uses it as a column default).
 */
export function nextBatch(migrations: MigrationMeta[], lastMillis: number | null): MigrationMeta[] {
  const batch: MigrationMeta[] = [];
  for (const m of migrations) {
    if (lastMillis !== null && lastMillis >= m.folderMillis) continue;
    batch.push(m);
    if (addsEnumValue(m)) break;
  }
  return batch;
}

/**
 * Brings the schema up to date. Works with node-postgres and PGlite handles.
 * Same bookkeeping as drizzle's migrator (`drizzle.__drizzle_migrations`, compatible with
 * drizzle-kit migrate). Each batch (see `nextBatch`) runs in one transaction under a
 * transaction-level advisory lock and re-reads the last applied migration, so several apps
 * starting at once do not race to create the same types and fail.
 */
export async function migrate(db: Db, opts: MigrateOptions = {}): Promise<void> {
  const migrations = opts.migrationsFolder
    ? readMigrationFiles({ migrationsFolder: opts.migrationsFolder })
    : embeddedMigrations();
  for (;;) {
    const applied = await db.transaction(async (t) => {
      await t.execute(sql`select pg_advisory_xact_lock(${MIGRATE_LOCK_KEY})`);
      await t.execute(sql`create schema if not exists "drizzle"`);
      await t.execute(sql`create table if not exists "drizzle"."__drizzle_migrations" (
        id serial primary key,
        hash text not null,
        created_at bigint
      )`);
      const res = await t.execute(
        sql`select id, hash, created_at from "drizzle"."__drizzle_migrations" order by created_at desc limit 1`,
      );
      const rows = (Array.isArray(res) ? res : ((res as { rows?: unknown[] }).rows ?? [])) as {
        created_at: string | number | null;
      }[];
      const last = rows[0];
      const batch = nextBatch(migrations, last ? Number(last.created_at) : null);
      for (const m of batch) {
        for (const stmt of m.sql) await t.execute(sql.raw(stmt));
        await t.execute(
          sql`insert into "drizzle"."__drizzle_migrations" ("hash", "created_at") values (${m.hash}, ${m.folderMillis})`,
        );
      }
      return batch.length;
    });
    if (applied === 0) return;
  }
}

const DEFAULT_URL = 'postgres://skirm:skirm@localhost:5432/skirm';

/**
 * Opens a one-connection pool on `url` (DATABASE_URL, contract default), applies every pending
 * migration and closes the pool. Safe to call from an app bootstrap; no side effects on import.
 */
export async function runMigrateCli(url = process.env.DATABASE_URL || DEFAULT_URL): Promise<void> {
  const db = createDb(url, { max: 1 });
  try {
    await migrate(db);
    console.log('[migrate] schema up to date');
  } finally {
    await closeDb(db);
  }
}
